using System.Collections.Generic;

public class StablePriorityQueue
{
    private class Item
    {
        public int Priority;
        public string Value = "";
    }

    private readonly List<Item> _items = new();

    public void Push(int priority, string value)
    {
        _items.Add(new Item { Priority = priority, Value = value });
        _items.Sort((a, b) => a.Priority.CompareTo(b.Priority));
    }

    public string Pop()
    {
        var item = _items[0];
        _items.RemoveAt(0);
        return item.Value;
    }
}

