using System.Collections.Generic;
using System.Linq;

public class StablePriorityQueue
{
    private class Item
    {
        public int Priority;
        public long Order;
        public string Value = "";
    }

    private readonly List<Item> _items = new();
    private long _counter;

    public void Push(int priority, string value)
    {
        _items.Add(new Item { Priority = priority, Order = _counter++, Value = value });
        _items.Sort((a, b) =>
        {
            var cmp = a.Priority.CompareTo(b.Priority);
            return cmp != 0 ? cmp : a.Order.CompareTo(b.Order);
        });
    }

    public string Pop()
    {
        var item = _items[0];
        _items.RemoveAt(0);
        return item.Value;
    }
}

