using Xunit;

public class StablePriorityQueueTests
{
    [Fact]
    public void PriorityOrder()
    {
        var q = new StablePriorityQueue();
        q.Push(5, "low");
        q.Push(1, "high");
        q.Push(3, "mid");
        Assert.Equal("high", q.Pop());
        Assert.Equal("mid", q.Pop());
        Assert.Equal("low", q.Pop());
    }

    [Fact]
    public void EqualPriorityIsFifoAcrossManyItems()
    {
        var q = new StablePriorityQueue();
        for (int i = 0; i < 20; i++)
        {
            q.Push(1, ((char)('a' + i)).ToString());
        }
        for (int i = 0; i < 20; i++)
        {
            Assert.Equal(((char)('a' + i)).ToString(), q.Pop());
        }
    }
}
